import AVFoundation

enum SoundEffect: String {
    /// Two warm "bloops" for "you're in". Generated by Tools/generate_signin_sound.py.
    case signInSuccess = "signin-success"
    /// A pop and a friendly "hel-lo!" for a new customer, timed to the header's waving hand.
    /// Generated by Tools/generate_welcome_sound.py.
    case welcomeNew = "welcome-new"
}

/// Interface sounds. They use the ambient category: silenced by the Ring/Silent switch and mixed
/// with whatever else is playing, never interrupting someone's music.
final class SoundEffects {
    static let shared = SoundEffects()

    private var players: [SoundEffect: AVAudioPlayer] = [:]
    private var sessionReady = false

    /// Loads the sound ahead of time so it starts on the exact frame it's asked for.
    func prepare(_ effect: SoundEffect) {
        _ = player(for: effect)
    }

    /// Plays from the start, optionally scheduled on the audio clock so it lands on an exact beat
    /// of an animation.
    func play(_ effect: SoundEffect, after delay: TimeInterval = 0) {
        guard let player = player(for: effect) else { return }
        player.stop()
        player.currentTime = 0
        if delay > 0 {
            player.play(atTime: player.deviceCurrentTime + delay)
        } else {
            player.play()
        }
    }

    private func player(for effect: SoundEffect) -> AVAudioPlayer? {
        if let player = players[effect] { return player }
        guard let url = Bundle.main.url(forResource: effect.rawValue, withExtension: "wav"),
              let player = try? AVAudioPlayer(contentsOf: url) else { return nil }
        configureSession()
        player.volume = 0.8
        player.prepareToPlay()
        players[effect] = player
        return player
    }

    private func configureSession() {
        guard !sessionReady else { return }
        sessionReady = true
        try? AVAudioSession.sharedInstance().setCategory(.ambient, options: [.mixWithOthers])
    }
}
